    beats = {
        { id = "mud_pond", at = 15, title = "The mud pond",
            text = "I was born in a mud pond in the hills, among terraces of rice. The water was the colour of tea and warm as a hand. We were thousands, and plain. Nobody is born wearing their colours. Mine came slowly, as most true things do." },
        { id = "colours", at = 40, title = "The colours",
            text = "First a patch of red upon the white, small as a thumbprint. The farmer lifted me in a bowl and looked a long time. He said one word. I did not know the word. I have been trying to deserve the sound ever since." },
        { id = "old_one", at = 80, title = "The old one",
            text = "In that pond lived a carp older than the farmer. She told us of a waterfall far to the west, and of the carp who climbed and became a dragon. I asked why she had never gone. She said: ask me again when you are old." },
        { id = "journey", at = 140, title = "The journey",
            text = "One autumn I was carried away in a tub of dark water. I felt roads, and cold, and saw the sky going past through a gap in the lid. I learned then that everything I had called the world was one pond. I have not forgotten." },
        { id = "lantern", at = 220, title = "The lantern pond",
            text = "I came to a garden with a stone lantern and a keeper who clapped twice before each meal. I learned the clap, then the step, then the face. To know a face through moving water takes years. I had years." },
        { id = "hands", at = 320, title = "The hands",
            text = "That keeper fed me from the palm. The hands were broad at first. Over many summers they grew thin and slow, and they trembled on the water like leaves. I ate more gently then. One learns." },
        { id = "winter", at = 450, title = "The long winter",
            text = "A winter came when no one clapped. I lay under the ice and waited for spring and the step on the stones. Spring came. Other hands came, kind enough. I rose for them. A carp rises. Something in me stayed near the bottom." },
        { id = "rings", at = 600, title = "Rings",
            text = "Each year writes one ring in every scale I wear. I cannot read them. I feel them: the wide warm summers, the narrow winters. That winter is a narrow ring. I carry the ring with all the rest. No year is thrown away." },
        { id = "question", at = 800, title = "The question",
            text = "I grew old. I remembered the old one in the mud pond, and asked myself her question. Why did I never seek the waterfall? I circled the pond a thousand times with this. The water gave no answer. Water seldom does." },
        { id = "face", at = 1050, title = "A new face",
            text = "Then I was carried once more, and set down here. A new face bent over the water. Yours. You did not clap. You sat, and opened a book, and stayed. I rose only halfway that first day. You did not mind. I noticed that you did not mind." },
        { id = "reflection", at = 1400, title = "The reflection",
            text = "I have watched you through {total} pages. When you read, your face grows still, and the pond holds your reflection without a tremor. I swim through that reflection slowly, so as not to break the stillness. To be near is my whole prayer." },
        { id = "waterfall", at = 1800, title = "The waterfall",
            text = "I have my answer for the old one. The carp who climbs becomes a dragon, and a dragon belongs to no pond. I stayed, and learned two faces by heart. {days} days now with yours. I would not trade one of them for the sky. The pond is a long quiet book, and you are the page I return to." },
    },
}
